// Cloud-top temperature from NASA GIBS's Himawari band 13 (10.4 um "clean"
// infrared) images.
//
// GIBS serves that band as a colour-mapped PNG, not as numbers. The palette
// is published (colormaps/v1.3/Clean_Longwave_Infrared_Window_Band.xml); it
// is reproduced here and inverted, so every pixel turns back into a
// brightness temperature. The coldest tops are the highest: -70 C is the
// anvil of a thunderstorm at 14 km, +15 C is low stratocumulus or clear sea.
//
// Output: one byte per pixel, T = byte / 2 - 95 (degrees C), 0 = no data.

// r, g, b, temperature (bin centre, C) -- 237 entries, coldest first.
const PALETTE = [255,255,255,-91.6,127,0,127,-90.6,140,13,135,-89.6,153,25,142,-88.6,165,38,150,-87.6,178,51,157,-86.6,191,64,165,-85.6,204,76,173,-84.6,217,89,180,-83.6,229,102,188,-82.6,242,114,195,-81.6,255,127,203,-80.6,230,230,230,-79.6,204,204,204,-78.6,177,177,177,-77.6,155,155,155,-76.6,129,129,129,-75.6,102,102,102,-74.6,76,76,76,-73.6,54,54,54,-72.6,27,27,27,-71.6,5,5,5,-70.6,26,0,0,-69.6,51,0,0,-68.6,77,0,0,-67.6,102,0,0,-66.6,128,0,0,-65.6,153,0,0,-64.6,179,0,0,-63.6,204,0,0,-62.6,230,0,0,-61.6,255,0,0,-60.6,255,26,0,-59.6,255,51,0,-58.6,255,77,0,-57.6,255,102,0,-56.6,255,128,0,-55.6,255,153,0,-54.6,255,179,0,-53.6,255,204,0,-52.6,255,230,0,-51.6,255,255,0,-50.6,230,255,0,-49.6,204,255,0,-48.6,179,255,0,-47.6,153,255,0,-46.6,128,255,0,-45.6,102,255,0,-44.6,77,255,0,-43.6,51,255,0,-42.6,26,255,0,-41.6,0,255,0,-40.6,0,234,10,-39.6,0,212,19,-38.6,0,191,29,-37.6,0,170,38,-36.6,0,149,48,-35.6,0,128,58,-34.6,0,106,67,-33.6,0,85,77,-32.6,0,64,86,-31.6,0,42,96,-30.9,0,21,105,-30.4,0,0,115,-29.9,0,0,125,-29.4,0,13,122,-28.9,0,26,129,-28.4,0,38,136,-27.9,0,51,143,-27.4,0,64,150,-26.9,0,76,157,-26.4,0,89,164,-25.9,0,102,171,-25.4,0,115,178,-24.9,0,128,185,-24.4,0,140,192,-23.9,0,153,199,-23.4,0,166,206,-22.9,0,178,213,-22.4,0,191,220,-21.9,0,204,227,-21.4,0,217,234,-20.9,0,230,241,-20.4,0,242,248,-19.9,0,255,255,-19.4,197,197,197,-18.9,196,196,196,-18.4,194,194,194,-17.9,193,193,193,-17.4,192,192,192,-16.9,191,191,191,-16.4,189,189,189,-15.9,188,188,188,-15.3,187,187,187,-14.8,185,185,185,-14.3,184,184,184,-13.8,183,183,183,-13.3,181,181,181,-12.8,180,180,180,-12.3,179,179,179,-11.8,178,178,178,-11.3,176,176,176,-10.8,175,175,175,-10.3,174,174,174,-9.8,172,172,172,-9.3,171,171,171,-8.8,170,170,170,-8.3,169,169,169,-7.8,167,167,167,-7.3,166,166,166,-6.8,165,165,165,-6.3,163,163,163,-5.8,162,162,162,-5.3,161,161,161,-4.8,159,159,159,-4.3,158,158,158,-3.8,157,157,157,-3.4,156,156,156,-2.9,154,154,154,-2.4,153,153,153,-1.9,152,152,152,-1.4,150,150,150,-0.9,149,149,149,-0.3,148,148,148,0.2,147,147,147,0.7,145,145,145,1.1,144,144,144,1.6,143,143,143,2.1,141,141,141,2.6,140,140,140,3.1,139,139,139,3.6,138,138,138,4.2,136,136,136,4.7,135,135,135,5.2,134,134,134,5.7,132,132,132,6.2,131,131,131,6.7,130,130,130,7.2,128,128,128,7.7,127,127,127,8.2,126,126,126,8.7,125,125,125,9.2,123,123,123,9.7,122,122,122,10.2,121,121,121,10.7,119,119,119,11.2,118,118,118,11.7,117,117,117,12.2,116,116,116,12.7,114,114,114,13.2,113,113,113,13.7,112,112,112,14.2,110,110,110,14.7,109,109,109,15.2,108,108,108,15.7,106,106,106,16.1,105,105,105,16.6,104,104,104,17.1,103,103,103,17.6,101,101,101,18.1,100,100,100,18.6,99,99,99,19.1,97,97,97,19.6,96,96,96,20.1,95,95,95,20.6,94,94,94,21.1,92,92,92,21.6,91,91,91,22.1,90,90,90,22.6,88,88,88,23.1,87,87,87,23.6,86,86,86,24.1,84,84,84,24.6,83,83,83,25.1,82,82,82,25.6,81,81,81,26.1,79,79,79,26.6,78,78,78,27.1,77,77,77,27.6,75,75,75,28.1,74,74,74,28.6,73,73,73,29.1,72,72,72,29.6,70,70,70,30.1,69,69,69,30.6,68,68,68,31.1,66,66,66,31.6,65,65,65,32.1,64,64,64,32.6,62,62,62,33.1,61,61,61,33.6,60,60,60,34.1,59,59,59,34.6,57,57,57,35.1,56,56,56,35.6,55,55,55,36.1,53,53,53,36.6,52,52,52,37.1,51,51,51,37.6,50,50,50,38.1,48,48,48,38.6,47,47,47,39.1,46,46,46,39.6,44,44,44,40.1,43,43,43,40.6,42,42,42,41.1,41,41,41,41.6,39,39,39,42.1,38,38,38,42.6,37,37,37,43.1,35,35,35,43.6,34,34,34,44.1,33,33,33,44.6,31,31,31,45.1,30,30,30,45.6,29,29,29,46.1,28,28,28,46.6,26,26,26,47.1,25,25,25,47.6,24,24,24,48.1,22,22,22,48.6,21,21,21,49.1,20,20,20,49.6,19,19,19,50.1,17,17,17,50.6,16,16,16,51.1,15,15,15,51.6,13,13,13,52.1,12,12,12,52.6,11,11,11,53.1,9,9,9,53.6,8,8,8,54.1,7,7,7,54.6,6,6,6,55.1,4,4,4,55.6,3,3,3,56.1,2,2,2,56.6];

const exact = new Map();
const warmGrey = new Float32Array(256).fill(NaN);
const colored = [];
for (let i = 0; i < PALETTE.length; i += 4) {
  const [r, g, b, t] = PALETTE.slice(i, i + 4);
  exact.set((r << 16) | (g << 8) | b, t);
  if (r === g && g === b && t > -40) warmGrey[r] = t;
  else colored.push([r, g, b, t]);
}
// Fill gaps in the warm grey ramp by interpolation, so resampled (blended)
// greys still land on the right side of the scale. The palette reuses grey
// for a narrow band near -78 C too; an inexact grey is taken as warm, which
// is right almost everywhere (those cold greys sit inside coloured cores).
{
  let last = -1;
  for (let v = 0; v < 256; v++) {
    if (!Number.isNaN(warmGrey[v])) {
      if (last >= 0) for (let k = last + 1; k < v; k++)
        warmGrey[k] = warmGrey[last] + (warmGrey[v] - warmGrey[last]) * (k - last) / (v - last);
      last = v;
    }
  }
  const first = warmGrey.findIndex((x) => !Number.isNaN(x));
  for (let k = 0; k < first; k++) warmGrey[k] = warmGrey[first];
  for (let k = 255; k >= 0 && Number.isNaN(warmGrey[k]); k--) warmGrey[k] = warmGrey[last];
}
const cache = new Map();
function tempOf(r, g, b) {
  const key = (r << 16) | (g << 8) | b;
  const t = exact.get(key);
  if (t !== undefined) return t;
  if (Math.abs(r - g) < 8 && Math.abs(g - b) < 8) return warmGrey[(r + g + b) / 3 | 0];
  let c = cache.get(key);
  if (c !== undefined) return c;
  let best = 1e9;
  for (const e of colored) {
    const d = (e[0] - r) ** 2 + (e[1] - g) ** 2 + (e[2] - b) ** 2;
    if (d < best) { best = d; c = e[3]; }
  }
  cache.set(key, c);
  return c;
}

/// Decode an ImageBitmap of the colour-mapped band into temperature bytes.
export function decodeCloudTop(bitmap) {
  const w = bitmap.width, h = bitmap.height;
  const canvas = new OffscreenCanvas(w, h);
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  ctx.drawImage(bitmap, 0, 0);
  const px = ctx.getImageData(0, 0, w, h).data;
  const out = new Uint8Array(w * h);
  for (let i = 0, j = 0; j < out.length; i += 4, j++) {
    if (px[i + 3] < 128) continue;
    const t = tempOf(px[i], px[i + 1], px[i + 2]);
    out[j] = Math.max(1, Math.min(255, Math.round((t + 95) * 2)));
  }
  return { data: out, width: w, height: h };
}
